50	// nullopt on any load_state failure (missing / short / bad magic / wrong
51	// version) -- a stale or corrupt cache entry means "capture again", never
52	// an aborted run.
53	inline auto try_load_reset_baseline(const std::filesystem::path& p)
54	  -> std::optional<hybrid_state_v1>
55	{
56	  try {
57	    return load_state(p.string());
58	  } catch (const std::exception&) {
59	    return std::nullopt;
60	  }
61	}
