63	// Create parent directories and write the raw struct. False on any failure
64	// -- the cache is an optimization, never a reason to abort a run.
65	inline auto save_reset_baseline(const std::filesystem::path& p,
66	                                const hybrid_state_v1& s) -> bool
67	{
68	  std::error_code ec;
69	  if (p.has_parent_path())
70	    std::filesystem::create_directories(p.parent_path(), ec);
71	  std::ofstream f(p, std::ios::binary | std::ios::trunc);
72	  if (!f) return false;
73	  f.write(reinterpret_cast<const char*>(&s), sizeof s);
74	  return static_cast<bool>(f);
